 static void ok(boolean b,String s){if(!b)throw new AssertionError(s);}static Player actor(){Player p=BossRoutesCheck.actor();p.lastSpear=0;p.switchDelay=0;return p;}static void clear(Player p){ToaSoloPlayableCheck.clear(p);}
